import React, { useState, useEffect } from "react";
import api from "@landinghub/api"; // hoặc axios
import LeadKanban from "../components/LeadKanban";
import LeadForm from "../components/LeadForm";

const Leads = () => {
  const [leads, setLeads] = useState([]);
  const [view, setView] = useState("kanban");
  const [draggedLead, setDraggedLead] = useState(null);

  const fetchLeads = async () => {
    try {
      const res = await api.get("/leads");
      setLeads(res.data.data || []);
    } catch {
      // Mock dữ liệu nếu API lỗi
      setLeads([
        { _id: "1", name: "Nguyễn Văn A", email: "a@gmail.com", phone: "0901", status: "new" },
        { _id: "2", name: "Trần Thị B", email: "b@gmail.com", phone: "0902", status: "processing" },
        { _id: "3", name: "Phạm C", email: "c@gmail.com", phone: "0903", status: "converted" },
      ]);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, []);

  const onAdd = async (form) => {
    const newLead = { ...form, status: "new" };
    try {
      const res = await api.post("/leads", newLead);
      setLeads([...leads, res.data]);
    } catch {
      setLeads([...leads, { ...newLead, _id: Date.now().toString() }]);
    }
  };

  const onDelete = async (id) => {
    if (!window.confirm("Xóa lead này?")) return;
    try {
      await api.delete(`/leads/${id}`);
      setLeads(leads.filter((l) => l._id !== id));
    } catch {
      setLeads(leads.filter((l) => l._id !== id));
    }
  };

  const onDragStart = (lead) => setDraggedLead(lead);
  const onDrop = async (newStatus) => {
    if (!draggedLead) return;
    const updated = { ...draggedLead, status: newStatus };
    setLeads(leads.map((l) => (l._id === draggedLead._id ? updated : l)));

    try {
      await api.put(`/leads/${draggedLead._id}`, { status: newStatus });
    } catch {}
    setDraggedLead(null);
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>📊 Quản lý Leads</h2>
      <div style={{ marginBottom: "20px" }}>
        <button onClick={() => setView("kanban")} disabled={view === "kanban"}>
          🧩 Kanban
        </button>
        <button onClick={() => setView("list")} disabled={view === "list"}>
          📋 Danh sách
        </button>
      </div>

      <LeadForm onAdd={onAdd} />

      {view === "kanban" ? (
        <LeadKanban
          leads={leads}
          onDragStart={onDragStart}
          onDrop={onDrop}
          onDelete={onDelete}
        />
      ) : (
        <table border="1" cellPadding="6" width="100%">
          <thead>
            <tr>
              <th>Tên</th>
              <th>Email</th>
              <th>Phone</th>
              <th>Trạng thái</th>
              <th>Hành động</th>
            </tr>
          </thead>
          <tbody>
            {leads.map((lead) => (
              <tr key={lead._id}>
                <td>{lead.name}</td>
                <td>{lead.email}</td>
                <td>{lead.phone}</td>
                <td>{lead.status}</td>
                <td>
                  <button onClick={() => onDelete(lead._id)}>❌</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default Leads;
